export const PHYSICAL_SCIENCES_BASICS_A_QUIZZES = [
  {
    id:`cp101`, cat:`Physical Sciences`, title:`Density, Buoyancy & Archimedes' Principle`, diff:`Easy`,
    qs:[
      { q:`Density is defined as:`, ch:[`Mass divided by volume`,`Volume divided by mass`,`Weight divided by area`,`Mass times volume`], ans:0, exp:`Density = mass/volume, typically in g/cm³ or kg/m³. It tells you how much matter is packed into a given space.` },
      { q:`A block has a mass of 50 g and a volume of 25 cm³. Its density is:`, ch:[`0.5 g/cm³`,`2 g/cm³`,`1250 g/cm³`,`25 g/cm³`], ans:1, exp:`Density = mass/volume = 50 g / 25 cm³ = 2 g/cm³.` },
      { q:`An object floats in water when:`, ch:[`Its density is greater than water's`,`Its density equals water's exactly`,`Its density is less than water's`,`Its shape is round`], ans:2, exp:`Objects float when their average density is less than the density of the fluid they're placed in (water ≈ 1 g/cm³). Ice (≈0.92 g/cm³) floats on liquid water for this reason.` },
      { q:`Archimedes' principle states that the buoyant force on a submerged object equals:`, ch:[`The object's own weight`,`The atmospheric pressure on the object`,`Zero if the object is fully submerged`,`The weight of fluid displaced by the object`], ans:3, exp:`Archimedes' principle: buoyant force = weight of the fluid displaced by the object. This is why a boat's hull shape, which displaces a large volume of water, lets it float even though steel is denser than water.` },
      { q:`A ship made of steel (density much greater than water) can still float because:`, ch:[`Its hollow shape displaces enough water to equal its weight`,`Steel becomes less dense in water`,`Steel is naturally less dense than water`,`Ships use engines to stay afloat`], ans:0, exp:`The ship's hull encloses a large volume of air, so the ship's overall (average) density, including the enclosed air space, is less than water, even though the steel itself is denser than water.` },
      { q:`Which has the greatest density: a 10 g piece of cork with volume 20 cm³, or a 10 g piece of iron with volume 1.3 cm³?`, ch:[`They are equal`,`The iron`,`The cork`,`Cannot be determined`], ans:1, exp:`Cork density = 10/20 = 0.5 g/cm³. Iron density = 10/1.3 ≈ 7.7 g/cm³. Iron is much denser because the same mass occupies far less volume.` },
      { q:`As an object sinks deeper in a swimming pool, the water pressure on it:`, ch:[`Decreases`,`Stays exactly the same`,`Increases`,`Becomes zero`], ans:2, exp:`Fluid pressure increases with depth because there is more fluid weight pressing down from above. This is why deep-sea divers need special equipment to withstand higher pressure.` },
      { q:`A hot air balloon rises because:`, ch:[`Heated air inside is denser than the surrounding cool air`,`Hot air has no weight`,`The balloon material is lighter than air`,`Heated air inside is less dense than the surrounding cool air`], ans:3, exp:`Heating the air inside the balloon makes it expand and become less dense than the cooler air outside, so the buoyant force from the surrounding air exceeds the balloon's weight, and it rises.` },
      { q:`If you place an ice cube in a glass of water and it melts, what happens to the water level?`, ch:[`It stays essentially the same`,`It rises noticeably`,`It drops noticeably`,`The glass overflows`], ans:0, exp:`Floating ice already displaces a volume of water equal to its own weight. When it melts into water of that same weight, it takes up the same volume, so the water level stays essentially unchanged.` },
      { q:`A rock weighs 30 N in air and 20 N when fully submerged in water. The buoyant force on the rock is:`, ch:[`50 N`,`10 N`,`30 N`,`20 N`], ans:1, exp:`Buoyant force = weight in air - apparent weight in water = 30 N - 20 N = 10 N. This equals the weight of the water displaced by the rock.` },
      { q:`Which of these objects would most likely sink in fresh water (density 1.0 g/cm³)?`, ch:[`An object with density 0.8 g/cm³`,`An object with density 0.95 g/cm³`,`An object with density 1.5 g/cm³`,`An object with density 1.0 g/cm³ exactly`], ans:2, exp:`Any object denser than the fluid it's placed in will sink. An object of density 1.5 g/cm³ is denser than water (1.0 g/cm³) and sinks.` },
      { q:`Two objects have the same mass but Object A has twice the volume of Object B. Which statement is true?`, ch:[`A and B have the same density`,`A is twice as dense as B`,`Density cannot be compared without knowing shape`,`B is twice as dense as A`], ans:3, exp:`Density = mass/volume. With equal mass but A having twice the volume of B, A's density is half of B's, meaning B is twice as dense as A.` },
    ]
  },
  {
    id:`cp102`, cat:`Physical Sciences`, title:`Simple Machines: Levers, Pulleys & Inclined Planes`, diff:`Easy`,
    qs:[
      { q:`A simple machine is a device that:`, ch:[`Changes the amount, direction, or distance of an applied force`,`Creates energy from nothing`,`Only works with electricity`,`Always reduces the work needed`], ans:0, exp:`Simple machines like levers, pulleys, and inclined planes make tasks easier by changing the size, direction, or distance over which a force acts — they don't create energy.` },
      { q:`In an ideal (frictionless) simple machine, the work input equals:`, ch:[`Twice the work output`,`The work output`,`Half the work output`,`Zero`], ans:1, exp:`Ideal simple machines conserve energy: work input = work output (W = F × d). A machine can trade a smaller force over a larger distance for a larger force over a smaller distance, but total work stays the same.` },
      { q:`A see-saw balanced on a central fulcrum is an example of which class of lever?`, ch:[`Second-class lever`,`Third-class lever`,`First-class lever`,`Not a lever at all`], ans:2, exp:`In a first-class lever, the fulcrum sits between the effort and the load (like a see-saw or scissors). This is different from a wheelbarrow (second-class, load between fulcrum and effort) or tweezers (third-class, effort between fulcrum and load).` },
      { q:`A wheelbarrow, where the load sits between the wheel (fulcrum) and the handles (effort), is an example of a:`, ch:[`First-class lever`,`Third-class lever`,`Pulley system`,`Second-class lever`], ans:3, exp:`In a second-class lever, the load is positioned between the fulcrum and the effort, as in a wheelbarrow or a bottle opener. This arrangement always gives a mechanical advantage greater than 1.` },
      { q:`Mechanical advantage of a simple machine is defined as:`, ch:[`Output force divided by input force`,`Input force divided by output force`,`Work input divided by work output`,`Distance moved by the effort`], ans:0, exp:`Mechanical advantage (MA) = output force (load) / input force (effort). An MA greater than 1 means the machine multiplies the applied force.` },
      { q:`A lever has the fulcrum 1 m from the load and 4 m from where the effort is applied. Its ideal mechanical advantage is:`, ch:[`0.25`,`4`,`1`,`5`], ans:1, exp:`For a lever, ideal MA = effort arm length / load arm length = 4 m / 1 m = 4. A smaller effort force applied over the longer arm can lift a larger load.` },
      { q:`Using a pulley system with 3 supporting rope segments to lift a load, the ideal mechanical advantage is approximately:`, ch:[`1`,`9`,`3`,`1/3`], ans:2, exp:`For a pulley system, ideal mechanical advantage roughly equals the number of rope segments supporting the load — here 3, meaning the effort force needed is about one-third of the load's weight.` },
      { q:`An inclined plane makes lifting a heavy box easier mainly by:`, ch:[`Reducing the total work needed`,`Eliminating gravity's effect`,`Increasing the box's weight`,`Spreading the same work over a longer distance, reducing the force needed`], ans:3, exp:`A ramp lets you push a box up a longer distance with less force than lifting it straight up, but the total work (force × distance) is about the same (ignoring friction) as lifting it vertically.` },
      { q:`A screw is best described as:`, ch:[`A wedge wrapped around a cylinder (an inclined plane in spiral form)`,`A type of lever only`,`A pulley with multiple wheels`,`A wheel and axle with no incline`], ans:0, exp:`A screw is essentially an inclined plane wrapped around a central cylinder. Turning it converts rotational force into a smaller force applied over the long spiral path, providing mechanical advantage.` },
      { q:`Which of the following is an example of a wheel-and-axle simple machine?`, ch:[`A seesaw`,`A doorknob`,`A ramp for wheelchairs`,`A pair of scissors`], ans:1, exp:`A doorknob is a wheel-and-axle machine: turning the wide knob (wheel) applies a small force over a large distance, which is converted to a larger force turning the narrow axle (the latch mechanism).` },
      { q:`Because real machines have friction, the actual mechanical advantage compared to the ideal (frictionless) mechanical advantage is:`, ch:[`Always exactly equal`,`Always greater`,`Always less`,`Unrelated to friction`], ans:2, exp:`Friction wastes some input energy as heat, so real machines always have actual mechanical advantage less than the theoretical ideal mechanical advantage calculated assuming no friction.` },
      { q:`Efficiency of a simple machine is calculated as:`, ch:[`(Work input / Work output) × 100%`,`Mechanical advantage × 100%`,`Force output minus force input`,`(Work output / Work input) × 100%`], ans:3, exp:`Efficiency = (useful work output / total work input) × 100%. Because of friction, real machines are always less than 100% efficient — some input energy is lost as heat.` },
    ]
  },
  {
    id:`cp103`, cat:`Physical Sciences`, title:`Energy Conservation & Transformation Basics`, diff:`Medium`,
    qs:[
      { q:`The law of conservation of energy states that energy:`, ch:[`Can neither be created nor destroyed, only transformed`,`Can be created but not destroyed`,`Can be destroyed but not created`,`Is always lost as heat over time`], ans:0, exp:`Energy cannot be created or destroyed — it only changes from one form to another (e.g., chemical to kinetic) or is transferred between objects. The total energy of an isolated system stays constant.` },
      { q:`A ball held above the ground has mostly which type of energy?`, ch:[`Kinetic energy`,`Gravitational potential energy`,`Thermal energy`,`Chemical energy`], ans:1, exp:`An object held at height has gravitational potential energy due to its position in Earth's gravitational field, given by PE = mgh, where h is height above a reference point.` },
      { q:`As a ball falls freely toward the ground (ignoring air resistance), its potential energy is converted into:`, ch:[`Chemical energy`,`Electrical energy`,`Kinetic energy`,`Nuclear energy`], ans:2, exp:`As height decreases, gravitational potential energy (PE = mgh) converts into kinetic energy (KE = ½mv²). Total mechanical energy (PE + KE) stays constant when air resistance is negligible.` },
      { q:`Kinetic energy is calculated using the formula:`, ch:[`KE = mgh`,`KE = Fd`,`KE = mv`,`KE = ½mv²`], ans:3, exp:`Kinetic energy = ½ × mass × velocity². Doubling an object's speed quadruples its kinetic energy, since velocity is squared in the formula.` },
      { q:`A 2 kg object moving at 3 m/s has a kinetic energy of:`, ch:[`9 J`,`3 J`,`6 J`,`18 J`], ans:0, exp:`KE = ½mv² = ½ × 2 kg × (3 m/s)² = ½ × 2 × 9 = 9 J.` },
      { q:`When a car's brakes are applied, most of the car's kinetic energy is converted into:`, ch:[`Potential energy`,`Thermal (heat) energy due to friction`,`Sound energy only`,`Chemical energy`], ans:1, exp:`Brake friction converts the car's kinetic energy mostly into thermal energy, heating the brake pads and rotors, along with some sound and a small amount of light.` },
      { q:`A battery-powered flashlight converts chemical energy into which two forms, primarily?`, ch:[`Nuclear and sound energy`,`Gravitational and elastic energy`,`Light and heat energy`,`Kinetic and magnetic energy`], ans:2, exp:`A flashlight converts stored chemical energy in the battery into electrical energy, which the bulb then converts mostly into light energy, with some energy lost as heat.` },
      { q:`A stretched rubber band or compressed spring stores what type of energy?`, ch:[`Nuclear potential energy`,`Gravitational potential energy`,`Kinetic energy`,`Elastic potential energy`], ans:3, exp:`Elastic potential energy is stored in an object due to its deformation (stretching or compression), such as in a spring or rubber band, and is released as the object returns to its natural shape.` },
      { q:`In an isolated (closed) system with no friction, the total mechanical energy (KE + PE):`, ch:[`Remains constant`,`Increases over time`,`Decreases over time`,`Becomes zero eventually`], ans:0, exp:`With no non-conservative forces like friction or air resistance acting, mechanical energy is conserved: total KE + PE stays constant, even as it converts back and forth between the two forms.` },
      { q:`A pendulum swings back and forth, losing a small amount of height (and speed) each swing due to air resistance. This is an example of:`, ch:[`Energy being created`,`Mechanical energy being converted to thermal energy and lost from the system`,`Perpetual motion`,`Kinetic energy increasing without bound`], ans:1, exp:`Air resistance is a non-conservative force that converts some of the pendulum's mechanical energy into heat, gradually reducing the pendulum's maximum height and speed until it eventually stops.` },
      { q:`Which scenario best demonstrates energy transformation from chemical to mechanical (kinetic) energy?`, ch:[`A solar panel charging in sunlight`,`Ice melting on a warm day`,`A car engine burning gasoline to accelerate the car`,`A magnet attracting a paperclip`], ans:2, exp:`Burning gasoline releases chemical energy stored in the fuel's molecular bonds, and the engine converts this into mechanical (kinetic) energy that moves the car.` },
      { q:`A 1000 kg roller coaster car sits at the top of a 20 m hill. Using g = 10 m/s² and ignoring friction, its potential energy at the top is:`, ch:[`2,000 J`,`20,000 J`,`2,000,000 J`,`200,000 J`], ans:3, exp:`PE = mgh = 1000 kg × 10 m/s² × 20 m = 200,000 J.` },
    ]
  },
  {
    id:`cp104`, cat:`Physical Sciences`, title:`Types of Chemical Reactions with Real Examples`, diff:`Easy`,
    qs:[
      { q:`In a synthesis (combination) reaction, two or more simple substances combine to form:`, ch:[`A single, more complex product`,`Two or more simpler products`,`Only gases`,`Nothing new; they stay separate`], ans:0, exp:`A synthesis reaction has the general form A + B → AB, where two or more reactants combine into one more complex product, such as 2H2 + O2 → 2H2O.` },
      { q:`2H2O → 2H2 + O2 (using electricity to split water) is an example of a:`, ch:[`Synthesis reaction`,`Decomposition reaction`,`Single-replacement reaction`,`Combustion reaction`], ans:1, exp:`A decomposition reaction breaks a single compound into two or more simpler substances (AB → A + B). Electrolysis of water splits H2O into hydrogen gas and oxygen gas.` },
      { q:`In the reaction Zn + CuSO4 → ZnSO4 + Cu, zinc replaces copper in the compound. This is an example of a:`, ch:[`Double-replacement reaction`,`Synthesis reaction`,`Single-replacement (displacement) reaction`,`Decomposition reaction`], ans:2, exp:`A single-replacement reaction has the form A + BC → AC + B, where one element displaces another in a compound. Here, more reactive zinc displaces copper from copper sulfate.` },
      { q:`AgNO3 + NaCl → AgCl + NaNO3 is best classified as a:`, ch:[`Combustion reaction`,`Synthesis reaction`,`Single-replacement reaction`,`Double-replacement (metathesis) reaction`], ans:3, exp:`A double-replacement reaction has the form AB + CD → AD + CB, where the positive ions (cations) of two compounds swap partners. Here Ag+ and Na+ trade places, forming solid AgCl and NaNO3.` },
      { q:`Combustion reactions, such as burning methane (CH4 + 2O2 → CO2 + 2H2O), always involve a substance reacting with:`, ch:[`Oxygen`,`Water`,`A metal`,`An acid`], ans:0, exp:`Combustion reactions involve a fuel (often a hydrocarbon) reacting rapidly with oxygen gas, releasing energy as heat and light, and commonly producing carbon dioxide and water for hydrocarbon fuels.` },
      { q:`Rusting of iron (4Fe + 3O2 → 2Fe2O3) is an example of which reaction type?`, ch:[`Decomposition`,`Synthesis (combination)`,`Double-replacement`,`Single-replacement`], ans:1, exp:`Rusting combines iron metal and oxygen gas into a single compound, iron(III) oxide, fitting the general synthesis pattern A + B → AB.` },
      { q:`A precipitate forming when two clear solutions are mixed (like mixing AgNO3 and NaCl solutions) is a common sign of a:`, ch:[`Combustion reaction`,`Physical change only, not a chemical reaction`,`Double-replacement reaction producing an insoluble solid`,`Nuclear reaction`], ans:2, exp:`When ions from two soluble compounds combine to form an insoluble solid (a precipitate), it signals a double-replacement reaction has occurred, such as AgCl forming as a white solid.` },
      { q:`Baking soda (NaHCO3) heated alone breaks down into sodium carbonate, water, and carbon dioxide. This is an example of a:`, ch:[`Synthesis reaction`,`Single-replacement reaction`,`Combustion reaction`,`Decomposition reaction`], ans:3, exp:`Heating a single compound to break it into multiple simpler products (2NaHCO3 → Na2CO3 + H2O + CO2) is a classic decomposition reaction, commonly seen in baking.` },
      { q:`Which of these is generally NOT a reliable sign that a chemical reaction has occurred?`, ch:[`A change in the container's shape`,`Formation of a gas (bubbling)`,`A color change`,`Release or absorption of heat (temperature change)`], ans:0, exp:`A container changing shape is unrelated to chemical change. Gas formation, color change, and heat release/absorption are all classic evidence that a chemical reaction (not just a physical change) has occurred.` },
      { q:`In the general reaction for combustion of a hydrocarbon fuel, the two main products are typically:`, ch:[`Hydrogen gas and oxygen gas`,`Carbon dioxide and water`,`Salt and water`,`A precipitate and a gas`], ans:1, exp:`Complete combustion of a hydrocarbon (containing only C and H) with sufficient oxygen produces carbon dioxide (CO2) and water (H2O), releasing energy as heat and light.` },
      { q:`Photosynthesis, 6CO2 + 6H2O → C6H12O6 + 6O2, driven by light energy, is most similar in structure to which reaction type?`, ch:[`Decomposition, since it breaks down CO2`,`Single-replacement, since one element swaps for another`,`Synthesis, since simple molecules combine into a more complex product (glucose)`,`Combustion, since it involves oxygen`], ans:2, exp:`Even though it's a multi-step biological process, overall photosynthesis combines simple molecules (CO2 and H2O) into a larger, more complex product (glucose), matching the pattern of a synthesis reaction.` },
    ]
  },
  {
    id:`cp105`, cat:`Physical Sciences`, title:`Intro to Redox Reactions`, diff:`Medium`,
    qs:[
      { q:`Oxidation is best defined as:`, ch:[`Gain of electrons`,`Gain of protons`,`Loss of protons`,`Loss of electrons`], ans:3, exp:`Oxidation is the loss of electrons by a substance. A helpful mnemonic is "OIL RIG": Oxidation Is Loss, Reduction Is Gain (of electrons).` },
      { q:`Reduction is best defined as:`, ch:[`Gain of electrons`,`Loss of electrons`,`Loss of mass`,`Gain of protons`], ans:0, exp:`Reduction is the gain of electrons by a substance, which typically lowers (reduces) its oxidation number. Oxidation and reduction always occur together in a redox reaction.` },
      { q:`In a redox reaction, the substance that loses electrons and causes another substance to be reduced is called the:`, ch:[`Oxidizing agent`,`Reducing agent`,`Catalyst`,`Precipitate`], ans:1, exp:`The reducing agent (or "reductant") donates electrons to another species, getting oxidized itself in the process, while causing the other substance to be reduced.` },
      { q:`In the reaction Zn + Cu2+ → Zn2+ + Cu, zinc is:`, ch:[`Reduced, because it loses electrons`,`Oxidized, because it gains electrons`,`Oxidized, because it loses electrons`,`Unchanged; only copper reacts`], ans:2, exp:`Zn goes from a neutral charge (0) to Zn2+, meaning it lost 2 electrons — this is oxidation. Meanwhile Cu2+ gains 2 electrons to become neutral Cu, so copper is reduced.` },
      { q:`The oxidation number of a free (uncombined) element, such as O2 or Na metal, is always:`, ch:[`+1`,`-1`,`+2`,`0`], ans:3, exp:`Any element in its free, uncombined state (not bonded to a different element) has an oxidation number of zero, whether it's a single atom like Na or a diatomic molecule like O2.` },
      { q:`In most compounds, oxygen has an oxidation number of:`, ch:[`-2`,`+2`,`-1`,`0`], ans:0, exp:`Oxygen is almost always -2 in compounds (a notable exception is peroxides like H2O2, where it is -1). This rule helps determine unknown oxidation numbers of other elements in a formula.` },
      { q:`A battery produces electricity by using a spontaneous redox reaction in which electrons flow through an external wire. This is an example of converting which form of energy to electrical energy?`, ch:[`Nuclear energy`,`Chemical energy`,`Gravitational potential energy`,`Sound energy`], ans:1, exp:`Batteries store chemical energy in their reactive materials; a spontaneous redox reaction releases electrons that flow through the external circuit as electrical current, converting chemical energy into electrical energy.` },
      { q:`Rusting of iron, 4Fe + 3O2 → 2Fe2O3, is a redox reaction in which:`, ch:[`Iron is reduced and oxygen is oxidized`,`Neither element changes oxidation state`,`Iron is oxidized and oxygen is reduced`,`Only oxygen changes oxidation state`], ans:2, exp:`Iron goes from oxidation state 0 to +3 (losing electrons, oxidized), while oxygen goes from 0 to -2 (gaining electrons, reduced). This is why rusting is classified as a redox process.` },
      { q:`Which of these processes is NOT a redox reaction?`, ch:[`Combustion of wood`,`Rusting of a nail`,`A battery discharging`,`Mixing NaCl and AgNO3 solutions to form a precipitate`], ans:3, exp:`Mixing NaCl and AgNO3 to precipitate AgCl is a double-replacement reaction where ions simply swap partners with no change in oxidation numbers — it is not a redox reaction, unlike combustion, rusting, and batteries.` },
      { q:`In photosynthesis, carbon in CO2 (oxidation state +4) becomes carbon in glucose (oxidation state close to 0). This change in carbon represents:`, ch:[`Reduction of carbon`,`Oxidation of carbon`,`No change in oxidation state`,`Neutralization`], ans:0, exp:`Carbon's oxidation state decreases from +4 in CO2 to about 0 in glucose, meaning carbon gains electrons overall — this is a reduction of carbon, driven by the energy from sunlight.` },
      { q:`During cellular respiration, glucose is broken down and oxygen is consumed to form CO2 and H2O. In this process, oxygen is:`, ch:[`Oxidized, since it gains electrons`,`Reduced, since it gains electrons`,`Reduced, since it loses electrons`,`Unreactive; it doesn't change oxidation state`], ans:1, exp:`Oxygen goes from oxidation state 0 (as O2 gas) to -2 (in H2O and CO2), gaining electrons — this is reduction. Meanwhile the carbon in glucose is oxidized as it's converted to CO2.` },
    ]
  },
  {
    id:`cp106`, cat:`Physical Sciences`, title:`Heating & Cooling Curves: Phase Changes Explained`, diff:`Easy`,
    qs:[
      { q:`On a heating curve for water, the flat (plateau) regions represent:`, ch:[`Times when temperature is rapidly increasing`,`Times when no energy is being added`,`Phase changes, where temperature stays constant while energy is added`,`Errors in measurement`], ans:2, exp:`During a phase change (like melting or boiling), added energy goes into breaking intermolecular forces rather than raising temperature, so the temperature stays constant, creating a flat plateau on the heating curve.` },
      { q:`The process of a solid changing directly into a gas without passing through the liquid phase is called:`, ch:[`Condensation`,`Deposition`,`Fusion`,`Sublimation`], ans:3, exp:`Sublimation is the direct solid-to-gas phase change, seen with dry ice (solid CO2) at room temperature and pressure, which turns straight into CO2 gas without ever becoming liquid.` },
      { q:`The reverse of sublimation — a gas turning directly into a solid — is called:`, ch:[`Deposition`,`Evaporation`,`Melting`,`Freezing`], ans:0, exp:`Deposition is the direct gas-to-solid phase change, seen when frost forms directly from water vapor in the air onto a cold surface without first becoming liquid.` },
      { q:`At 0°C and standard atmospheric pressure, ice and liquid water can coexist. This temperature is called water's:`, ch:[`Boiling point`,`Melting (freezing) point`,`Triple point exactly`,`Critical point`], ans:1, exp:`0°C at standard atmospheric pressure is water's melting point (equivalently freezing point) — the temperature at which solid and liquid phases are in equilibrium.` },
      { q:`During the process of boiling, energy added to the liquid is used to:`, ch:[`Increase the average kinetic energy (temperature) of the molecules`,`Decrease the molecules' potential energy`,`Overcome intermolecular forces so molecules can escape into the gas phase`,`Compress the liquid`], ans:2, exp:`At the boiling point, added heat (the latent heat of vaporization) goes into overcoming intermolecular attractions between liquid molecules so they can separate into gas, not into raising the temperature.` },
      { q:`Which correctly lists the phase changes from solid to gas as heat is continuously added?`, ch:[`Vaporization, then melting`,`Sublimation, then condensation`,`Freezing, then boiling`,`Melting, then vaporization`], ans:3, exp:`As heat is added to a solid, it first melts into a liquid (melting), and with further heating, the liquid vaporizes into a gas (vaporization/boiling).` },
      { q:`Condensation is the phase change where:`, ch:[`A gas becomes a liquid`,`A liquid becomes a solid`,`A solid becomes a gas`,`A liquid becomes a gas`], ans:0, exp:`Condensation occurs when a gas loses energy and its molecules slow down enough to be pulled together by intermolecular forces, forming a liquid, such as water vapor condensing into dew.` },
      { q:`During a phase change like melting, why does temperature remain constant even though heat is still being added?`, ch:[`Because heat stops flowing into the substance during melting`,`Because the added energy breaks intermolecular bonds (increasing potential energy) rather than increasing kinetic energy`,`Because the substance is losing mass`,`Because temperature cannot be measured during melting`], ans:1, exp:`Temperature reflects average kinetic energy of particles. During melting, added heat energy goes into overcoming intermolecular forces (raising potential energy), not increasing particle speed, so temperature holds steady until melting completes.` },
      { q:`On a standard cooling curve for water starting as steam, as the substance cools from gas to solid, the two flat plateaus correspond to:`, ch:[`Only freezing`,`Only condensation`,`Condensation (gas to liquid) and freezing (liquid to solid)`,`Sublimation and deposition`], ans:2, exp:`As steam cools, it first plateaus while condensing from gas to liquid (releasing heat of vaporization), then continues cooling as a liquid until it plateaus again while freezing into a solid (releasing heat of fusion).` },
      { q:`Which requires more energy per gram for water: vaporization (liquid to gas) or fusion (solid to liquid)?`, ch:[`Fusion requires more energy`,`They require exactly the same energy`,`Neither requires energy`,`Vaporization requires more energy`], ans:3, exp:`Water's latent heat of vaporization (about 2260 J/g) is roughly 6-7 times greater than its latent heat of fusion (about 334 J/g), because vaporization requires completely separating molecules into a gas, overcoming much stronger attractive forces than melting does.` },
      { q:`If you place an ice cube in a sealed container and heat it steadily, plotting temperature vs. time, the graph will show:`, ch:[`Two flat plateaus (at the melting point and boiling point) separated by rising segments`,`A single continuous rising line with no flat sections`,`A continuously falling line`,`One flat plateau only, at 100°C`], ans:0, exp:`The temperature rises as solid ice warms, plateaus at 0°C while melting, rises again as liquid water warms, then plateaus at 100°C while boiling, producing the classic heating curve shape with two flat regions.` },
    ]
  },
  {
    id:`cp107`, cat:`Physical Sciences`, title:`Unit Conversion & Dimensional Analysis`, diff:`Easy`,
    qs:[
      { q:`Dimensional analysis (using conversion factors) is a technique used to:`, ch:[`Solve for the roots of an equation`,`Convert a quantity from one unit to another using equivalent ratios`,`Determine the shape of a molecule`,`Balance chemical equations`], ans:1, exp:`Dimensional analysis uses conversion factors (ratios equal to 1, like 1 km/1000 m) to convert a measurement from one unit to an equivalent value in another unit, canceling out unwanted units along the way.` },
      { q:`How many centimeters are in 3.5 meters?`, ch:[`0.35 cm`,`35 cm`,`350 cm`,`3500 cm`], ans:2, exp:`1 m = 100 cm, so 3.5 m × 100 cm/m = 350 cm.` },
      { q:`Convert 2.5 kilograms to grams.`, ch:[`0.0025 g`,`25 g`,`250 g`,`2500 g`], ans:3, exp:`1 kg = 1000 g, so 2.5 kg × 1000 g/kg = 2500 g.` },
      { q:`A car travels at 60 miles per hour. What is this speed in miles per minute?`, ch:[`1 mile/min`,`60 miles/min`,`3600 miles/min`,`0.6 miles/min`], ans:0, exp:`There are 60 minutes in an hour, so 60 miles/hour ÷ 60 min/hour = 1 mile/minute.` },
      { q:`Which conversion factor would correctly convert a length measured in inches into feet? (1 foot = 12 inches)`, ch:[`12 inches / 1 foot`,`1 foot / 12 inches`,`1 inch / 1 foot`,`1 foot / 1 inch`], ans:1, exp:`To cancel inches and end up with feet, multiply by a fraction with inches in the denominator: (1 foot / 12 inches). Inches cancels, leaving feet.` },
      { q:`If a recipe requires 500 milliliters of water, how many liters is this?`, ch:[`5 L`,`50 L`,`0.5 L`,`5000 L`], ans:2, exp:`1 L = 1000 mL, so 500 mL ÷ 1000 mL/L = 0.5 L.` },
      { q:`A runner completes a 5-kilometer race in 25 minutes. What is the runner's average speed in kilometers per hour?`, ch:[`5 km/h`,`10 km/h`,`25 km/h`,`12 km/h`], ans:3, exp:`25 minutes = 25/60 hours ≈ 0.417 hours. Speed = distance/time = 5 km / 0.417 h ≈ 12 km/h.` },
      { q:`In dimensional analysis, when multiplying conversion factors together, unwanted units should:`, ch:[`Cancel out algebraically, leaving only the desired unit`,`Be added to the final answer`,`Always double`,`Be ignored regardless of placement`], ans:0, exp:`Conversion factors are set up so that matching units in the numerator of one factor and denominator of the next cancel algebraically, leaving only the target unit in the final answer.` },
      { q:`A metric prefix "kilo-" represents a factor of:`, ch:[`100`,`1000`,`10,000`,`0.001`], ans:1, exp:`The prefix "kilo-" means ×1000 (10³). For example, 1 kilometer = 1000 meters, and 1 kilogram = 1000 grams.` },
      { q:`How many milligrams are in 1 gram?`, ch:[`10 mg`,`100 mg`,`1000 mg`,`10,000 mg`], ans:2, exp:`The prefix "milli-" means ×0.001 (10⁻³), so there are 1000 milligrams in 1 gram (1 g = 1000 mg).` },
      { q:`A rectangular room measures 4 meters by 5 meters. What is its area in square feet? (1 meter ≈ 3.28 feet)`, ch:[`About 20 ft²`,`About 65.6 ft²`,`About 655 ft²`,`About 215 ft²`], ans:3, exp:`Area in m² = 4 × 5 = 20 m². Converting: 20 m² × (3.28 ft/m)² = 20 × 10.76 ft²/m² ≈ 215 ft². Note that when converting area, the conversion factor must be squared.` },
    ]
  },
  {
    id:`cp108`, cat:`Physical Sciences`, title:`Basic Trigonometry: SOH CAH TOA`, diff:`Medium`,
    qs:[
      { q:`In a right triangle, the mnemonic SOH CAH TOA helps you remember that sine equals:`, ch:[`Opposite / Hypotenuse`,`Adjacent / Hypotenuse`,`Opposite / Adjacent`,`Hypotenuse / Opposite`], ans:0, exp:`SOH: Sine = Opposite / Hypotenuse. The mnemonic organizes the three basic trig ratios for a right triangle relative to a chosen acute angle.` },
      { q:`According to CAH, cosine of an angle equals:`, ch:[`Opposite / Hypotenuse`,`Adjacent / Hypotenuse`,`Opposite / Adjacent`,`Hypotenuse / Adjacent`], ans:1, exp:`CAH: Cosine = Adjacent / Hypotenuse. This ratio compares the side next to the angle (not the hypotenuse) to the longest side of the right triangle.` },
      { q:`According to TOA, tangent of an angle equals:`, ch:[`Adjacent / Opposite`,`Opposite / Hypotenuse`,`Opposite / Adjacent`,`Hypotenuse / Adjacent`], ans:2, exp:`TOA: Tangent = Opposite / Adjacent. Tangent can also be derived as sine divided by cosine, since (Opp/Hyp) / (Adj/Hyp) = Opp/Adj.` },
      { q:`In a right triangle, the hypotenuse is:`, ch:[`The shortest side`,`Always adjacent to the right angle`,`Only used for isosceles triangles`,`The side opposite the right angle, and the longest side`], ans:3, exp:`The hypotenuse is the side directly across from the 90° angle, and it is always the longest side of a right triangle.` },
      { q:`A right triangle has a hypotenuse of 10 and one leg (opposite a given angle) of 6. Using the Pythagorean theorem, the other leg is:`, ch:[`8`,`4`,`6`,`16`], ans:0, exp:`Pythagorean theorem: a² + b² = c². 6² + b² = 10² → 36 + b² = 100 → b² = 64 → b = 8.` },
      { q:`For a right triangle with an angle θ where the opposite side = 3 and the hypotenuse = 5, sin(θ) equals:`, ch:[`5/3`,`3/5`,`4/5`,`3/4`], ans:1, exp:`sin(θ) = opposite/hypotenuse = 3/5 = 0.6.` },
      { q:`If sin(θ) = 0.5 for an acute angle θ, θ is approximately:`, ch:[`15°`,`45°`,`30°`,`60°`], ans:2, exp:`sin(30°) = 0.5 exactly, one of the standard reference angle values worth memorizing (along with sin 0°=0, sin 45°≈0.707, sin 60°≈0.866, sin 90°=1).` },
      { q:`A ladder leans against a wall, making a 60° angle with the ground, and the ladder is 10 m long. Approximately how high up the wall does it reach (use sin 60° ≈ 0.866)?`, ch:[`5 m`,`7 m`,`10 m`,`8.66 m`], ans:3, exp:`Height = hypotenuse × sin(angle) = 10 m × sin(60°) ≈ 10 × 0.866 = 8.66 m, since the height is the side opposite the 60° angle and the ladder is the hypotenuse.` },
      { q:`Which trigonometric identity is always true for any acute angle θ?`, ch:[`sin²(θ) + cos²(θ) = 1`,`sin(θ) + cos(θ) = 1`,`tan(θ) = sin(θ) + cos(θ)`,`sin(θ) = cos(θ) always`], ans:0, exp:`The Pythagorean trig identity sin²(θ) + cos²(θ) = 1 holds for all angles θ, and follows directly from the Pythagorean theorem applied to the unit circle or a right triangle with hypotenuse 1.` },
      { q:`For angles between 0° and 90°, as the angle θ increases, sin(θ):`, ch:[`Decreases`,`Increases`,`Stays constant`,`Oscillates unpredictably`], ans:1, exp:`Over the range 0° to 90°, sine is a monotonically increasing function, from sin(0°) = 0 up to sin(90°) = 1.` },
      { q:`A surveyor stands 50 m from the base of a tower and measures the angle of elevation to the top as 40°. Which trig ratio would directly give the tower's height (using the known adjacent side of 50 m)?`, ch:[`Height = 50 × sin(40°)`,`Height = 50 × cos(40°)`,`Height = 50 × tan(40°)`,`Height = 50 / tan(40°)`], ans:2, exp:`Since 50 m is the side adjacent to the angle and the height is the side opposite the angle, tan(θ) = opposite/adjacent, so height = 50 × tan(40°).` },
    ]
  },
  {
    id:`cp109`, cat:`Physical Sciences`, title:`Coordinate Geometry: Lines & Slopes`, diff:`Easy`,
    qs:[
      { q:`The slope of a line measures:`, ch:[`How far the line is from the origin`,`The length of the line`,`The x-intercept of the line`,`The steepness and direction of the line (rise over run)`], ans:3, exp:`Slope = rise/run = (change in y)/(change in x) between any two points on the line, describing how steeply and in what direction the line rises or falls.` },
      { q:`The slope between the points (2, 3) and (6, 11) is:`, ch:[`2`,`4`,`8`,`1/2`], ans:0, exp:`Slope = (y2-y1)/(x2-x1) = (11-3)/(6-2) = 8/4 = 2.` },
      { q:`In the slope-intercept form y = mx + b, the value b represents:`, ch:[`The slope of the line`,`The y-intercept`,`The x-intercept`,`The x-coordinate of the vertex`], ans:1, exp:`In y = mx + b, m is the slope and b is the y-intercept — the y-value where the line crosses the y-axis (at x = 0).` },
      { q:`A horizontal line has a slope of:`, ch:[`Undefined`,`1`,`0`,`Depends on the line's position`], ans:2, exp:`A horizontal line has no vertical change (rise = 0) as x changes, so its slope = 0/run = 0.` },
      { q:`A vertical line has a slope that is:`, ch:[`0`,`1`,`Negative`,`Undefined`], ans:3, exp:`A vertical line has no horizontal change (run = 0), and division by zero is undefined, so vertical lines have an undefined slope.` },
      { q:`Two lines are parallel if and only if they have:`, ch:[`The same slope`,`The same y-intercept`,`Slopes that are negative reciprocals of each other`,`Slopes that multiply to -1`], ans:0, exp:`Parallel lines never intersect and rise/fall at the same rate, meaning they must have identical slopes (but different y-intercepts, or they'd be the same line).` },
      { q:`Two lines are perpendicular if their slopes:`, ch:[`Are equal`,`Are negative reciprocals of each other (multiply to -1)`,`Are both zero`,`Add up to zero`], ans:1, exp:`Perpendicular lines meet at a 90° angle, and this occurs when the product of their slopes is -1 (e.g., slopes of 2 and -1/2).` },
      { q:`What is the equation, in slope-intercept form, of a line with slope 3 that passes through the point (0, -4)?`, ch:[`y = -4x + 3`,`y = 3x + 4`,`y = 3x - 4`,`y = -3x - 4`], ans:2, exp:`Since the line passes through (0, -4), the y-intercept b = -4. With slope m = 3, the equation is y = 3x - 4.` },
      { q:`A line has the equation y = -2x + 5. What is its slope and y-intercept?`, ch:[`Slope = 5, y-intercept = -2`,`Slope = 2, y-intercept = 5`,`Slope = -2, y-intercept = -5`,`Slope = -2, y-intercept = 5`], ans:3, exp:`Comparing to y = mx + b, m = -2 (slope) and b = 5 (y-intercept). The negative slope means the line falls from left to right.` },
      { q:`The distance between points (0, 0) and (3, 4) on a coordinate plane is:`, ch:[`5`,`3`,`4`,`7`], ans:0, exp:`Distance = √[(x2-x1)² + (y2-y1)²] = √(3² + 4²) = √(9+16) = √25 = 5, using the distance formula derived from the Pythagorean theorem.` },
      { q:`Which point lies on the line y = 2x - 1?`, ch:[`(1, 2)`,`(2, 3)`,`(0, 1)`,`(3, 4)`], ans:1, exp:`Substituting (2,3): y = 2(2) - 1 = 4 - 1 = 3, which matches, so (2, 3) is on the line. Checking (1,2): 2(1)-1=1≠2. Checking (0,1): 2(0)-1=-1≠1. Checking (3,4): 2(3)-1=5≠4.` },
    ]
  },
  {
    id:`cp110`, cat:`Physical Sciences`, title:`Systems of Equations Basics`, diff:`Medium`,
    qs:[
      { q:`A system of two linear equations with two variables (x and y) has a unique solution when the lines:`, ch:[`Are parallel`,`Are the same line`,`Intersect at exactly one point`,`Never touch`], ans:2, exp:`When two distinct, non-parallel lines are graphed, they cross at exactly one point, which represents the single (x, y) pair that satisfies both equations simultaneously.` },
      { q:`If a system of two linear equations represents two parallel, distinct lines, the system has:`, ch:[`Exactly one solution`,`Infinitely many solutions`,`Exactly two solutions`,`No solution`], ans:3, exp:`Parallel lines with different y-intercepts never intersect, so there is no (x,y) pair that satisfies both equations — the system has no solution.` },
      { q:`If a system of two linear equations describes the exact same line (identical equations in different forms), the system has:`, ch:[`Infinitely many solutions`,`No solution`,`Exactly one solution`,`Exactly two solutions`], ans:0, exp:`If both equations describe the same line, every point on that line satisfies both equations, giving infinitely many solutions.` },
      { q:`Solve the system: x + y = 10 and x - y = 4. What is x?`, ch:[`3`,`7`,`5`,`14`], ans:1, exp:`Adding both equations: (x+y) + (x-y) = 10 + 4 → 2x = 14 → x = 7. Then y = 10 - 7 = 3.` },
      { q:`Using the substitution method to solve y = 2x and x + y = 9, what is the value of x?`, ch:[`2`,`4`,`3`,`9`], ans:2, exp:`Substitute y = 2x into x + y = 9: x + 2x = 9 → 3x = 9 → x = 3. Then y = 2(3) = 6.` },
      { q:`In the elimination method for solving systems of equations, the goal is typically to:`, ch:[`Graph both equations`,`Multiply the two equations together`,`Substitute one equation directly into a graph`,`Add or subtract the equations to cancel out one variable`], ans:3, exp:`The elimination method multiplies one or both equations by constants (if needed) so that adding or subtracting them cancels out one variable, leaving a single-variable equation to solve.` },
      { q:`A system has equations y = 3x + 2 and y = 3x - 5. Without solving further, you can tell this system has:`, ch:[`No solution, because the lines are parallel with different y-intercepts`,`One solution`,`Infinitely many solutions`,`Cannot be determined`], ans:0, exp:`Both lines have the same slope (3) but different y-intercepts (2 and -5), meaning they are parallel and never intersect, so there is no solution.` },
      { q:`Two numbers have a sum of 15 and a difference of 5. What are the two numbers?`, ch:[`7 and 8`,`5 and 10`,`10 and 5`,`6 and 9`], ans:1, exp:`Let x+y=15 and x-y=5. Adding: 2x=20, x=10. Then y=15-10=5. The two numbers are 10 and 5.` },
      { q:`A movie theater sells adult tickets for $12 and child tickets for $8. If 5 tickets were sold for a total of $48, and a = number of adult tickets, c = number of child tickets, which system correctly represents this situation?`, ch:[`a + c = 48 and 12a + 8c = 5`,`a - c = 5 and 12a - 8c = 48`,`a + c = 5 and 12a + 8c = 48`,`a + c = 5 and 8a + 12c = 48`], ans:2, exp:`The total number of tickets is 5 (a + c = 5), and the total cost is 12 dollars per adult ticket plus 8 dollars per child ticket, summing to $48 (12a + 8c = 48).` },
      { q:`Solving the system from the ticket problem above (a + c = 5, 12a + 8c = 48), how many adult tickets were sold?`, ch:[`1`,`3`,`4`,`2`], ans:3, exp:`From a + c = 5, c = 5 - a. Substituting: 12a + 8(5-a) = 48 → 12a + 40 - 8a = 48 → 4a = 8 → a = 2. So 2 adult tickets were sold.` },
      { q:`A system of two linear equations can have at most how many distinct solutions (assuming the lines are not identical)?`, ch:[`One`,`Zero`,`Two`,`Infinitely many`], ans:0, exp:`Two distinct, non-identical straight lines can intersect at most at one single point, so a system of two non-identical linear equations has at most one solution.` },
    ]
  },
  {
    id:`cp111`, cat:`Physical Sciences`, title:`Sequences & Series Basics`, diff:`Medium`,
    qs:[
      { q:`In the arithmetic sequence 3, 7, 11, 15, ..., the common difference is:`, ch:[`3`,`4`,`7`,`11`], ans:1, exp:`An arithmetic sequence has a constant difference between consecutive terms. Here, 7-3=4, 11-7=4, 15-11=4, so the common difference d = 4.` },
      { q:`The formula for the nth term of an arithmetic sequence is:`, ch:[`aₙ = a₁ × rⁿ⁻¹`,`aₙ = a₁ / n`,`aₙ = a₁ + (n-1)d`,`aₙ = a₁ + nd²`], ans:2, exp:`For an arithmetic sequence, aₙ = a₁ + (n-1)d, where a₁ is the first term, d is the common difference, and n is the term number.` },
      { q:`For the arithmetic sequence 5, 9, 13, 17, ..., what is the 10th term?`, ch:[`37`,`45`,`13`,`41`], ans:3, exp:`a₁=5, d=4. a₁₀ = 5 + (10-1)(4) = 5 + 36 = 41.` },
      { q:`In a geometric sequence 2, 6, 18, 54, ..., the common ratio is:`, ch:[`3`,`2`,`4`,`6`], ans:0, exp:`A geometric sequence has a constant ratio between consecutive terms. Here, 6/2=3, 18/6=3, 54/18=3, so the common ratio r = 3.` },
      { q:`The formula for the nth term of a geometric sequence is:`, ch:[`aₙ = a₁ + (n-1)d`,`aₙ = a₁ × rⁿ⁻¹`,`aₙ = a₁ × n`,`aₙ = a₁ + rⁿ`], ans:1, exp:`For a geometric sequence, aₙ = a₁ × r^(n-1), where a₁ is the first term, r is the common ratio, and n is the term number.` },
      { q:`For the geometric sequence 3, 6, 12, 24, ..., what is the 6th term?`, ch:[`48`,`72`,`96`,`144`], ans:2, exp:`a₁=3, r=2. a₆ = 3 × 2^(6-1) = 3 × 32 = 96.` },
      { q:`The sum of the first n terms of an arithmetic sequence can be calculated using:`, ch:[`Sₙ = a₁ × rⁿ`,`Sₙ = n × d`,`Sₙ = (a₁ - aₙ)/n`,`Sₙ = n(a₁ + aₙ)/2`], ans:3, exp:`The arithmetic series sum formula is Sₙ = n(a₁ + aₙ)/2, which averages the first and last terms and multiplies by the number of terms.` },
      { q:`What is the sum of the first 5 terms of the arithmetic sequence 2, 5, 8, 11, 14?`, ch:[`40`,`14`,`45`,`55`], ans:0, exp:`Sum = n(a₁+aₙ)/2 = 5(2+14)/2 = 5(16)/2 = 5×8 = 40. (Check by adding: 2+5+8+11+14=40.)` },
      { q:`A ball is dropped and each bounce reaches half the height of the previous bounce. This describes what type of sequence?`, ch:[`Arithmetic, with common difference 1/2`,`Geometric, with common ratio 1/2`,`Neither arithmetic nor geometric`,`A constant sequence`], ans:1, exp:`Since each successive height is multiplied by the same factor (1/2) rather than having a constant difference, this is a geometric sequence with common ratio r = 1/2.` },
      { q:`Which of the following sequences is neither arithmetic nor geometric?`, ch:[`2, 4, 6, 8, 10`,`3, 9, 27, 81`,`1, 4, 9, 16, 25`,`10, 7, 4, 1, -2`], ans:2, exp:`1, 4, 9, 16, 25 are perfect squares (n²); the differences (3, 5, 7, 9) are not constant, and the ratios (4, 2.25, 1.78...) are not constant either, so it's neither arithmetic nor geometric.` },
      { q:`A savings plan starts with $100 and adds $50 each month. After how many months (including the starting month as month 1) will the total in that month's deposit reach $400?`, ch:[`5`,`6`,`8`,`7`], ans:3, exp:`This is arithmetic with a₁=100, d=50. Solve 100+(n-1)(50)=400 → (n-1)(50)=300 → n-1=6 → n=7.` },
    ]
  },
  {
    id:`cp112`, cat:`Physical Sciences`, title:`Number Theory Basics: Factors, Multiples & Primes`, diff:`Easy`,
    qs:[
      { q:`A prime number is defined as a whole number greater than 1 that:`, ch:[`Has exactly two positive factors: 1 and itself`,`Has no factors at all`,`Is always odd`,`Can be divided evenly by any number`], ans:0, exp:`A prime number has exactly two positive divisors: 1 and itself. Numbers with more than two factors (like 4, 6, 8, 9) are called composite numbers.` },
      { q:`Which of the following is a prime number?`, ch:[`9`,`17`,`15`,`21`], ans:1, exp:`17 is only divisible by 1 and 17. 9=3×3, 15=3×5, and 21=3×7 are all composite numbers with more than two factors.` },
      { q:`What is the only even prime number?`, ch:[`0`,`4`,`2`,`There is no even prime number`], ans:2, exp:`2 is the only even prime number. Every other even number is divisible by 2 as well as itself and 1, giving it more than two factors, making it composite.` },
      { q:`The prime factorization of 60 is:`, ch:[`2 × 30`,`2 × 3 × 10`,`4 × 15`,`2² × 3 × 5`], ans:3, exp:`60 = 2 × 30 = 2 × 2 × 15 = 2 × 2 × 3 × 5 = 2² × 3 × 5. This is the unique breakdown of 60 into prime factors.` },
      { q:`The greatest common factor (GCF) of 12 and 18 is:`, ch:[`6`,`2`,`3`,`36`], ans:0, exp:`Factors of 12: 1,2,3,4,6,12. Factors of 18: 1,2,3,6,9,18. The largest number appearing in both lists is 6.` },
      { q:`The least common multiple (LCM) of 4 and 6 is:`, ch:[`10`,`12`,`24`,`2`], ans:1, exp:`Multiples of 4: 4,8,12,16... Multiples of 6: 6,12,18... The smallest number appearing in both lists is 12.` },
      { q:`A number is divisible by 3 if:`, ch:[`It ends in 0, 3, or 6`,`It is an even number`,`The sum of its digits is divisible by 3`,`It ends in 3`], ans:2, exp:`The divisibility rule for 3: add up all the digits of the number; if that sum is divisible by 3, the original number is also divisible by 3. For example, 471: 4+7+1=12, which is divisible by 3, so 471 is too.` },
      { q:`Which number is a multiple of both 4 and 6?`, ch:[`10`,`14`,`30`,`24`], ans:3, exp:`24 = 4 × 6 = 6 × 4, so it's divisible by both 4 and 6. (It's actually their LCM.) 10 isn't divisible by 4 or 6 evenly by both; 14 isn't divisible by either 4 or 6; 30 is divisible by 6 but not by 4.` },
      { q:`Is the number 1 considered prime, composite, or neither?`, ch:[`Neither prime nor composite`,`Prime`,`Composite`,`Both prime and composite`], ans:0, exp:`By definition, prime numbers must have exactly two distinct factors (1 and itself). The number 1 has only one factor (itself), so it is classified as neither prime nor composite.` },
      { q:`Using prime factorization, 12 = 2² × 3 and 18 = 2 × 3². What is the GCF of 12 and 18 using these factorizations?`, ch:[`2² × 3² = 36`,`2 × 3 = 6`,`2 × 3² = 18`,`2² × 3 = 12`], ans:1, exp:`The GCF is found by taking the lowest power of each common prime factor: for 2, the lower power is 2¹; for 3, the lower power is 3¹. So GCF = 2 × 3 = 6.` },
      { q:`A school is arranging 24 students and 36 students from two classes into equal-sized groups, with no students left over and each group from the same class. What is the largest possible group size that works for both classes?`, ch:[`6`,`8`,`12`,`72`], ans:2, exp:`This requires the GCF of 24 and 36. 24 = 2³×3, 36 = 2²×3². GCF = 2²×3 = 12. Groups of 12 students each divide evenly into both 24 (2 groups) and 36 (3 groups).` },
    ]
  },
  {
    id:`cp113`, cat:`Physical Sciences`, title:`Intro to Astronomy: The Solar System`, diff:`Easy`,
    qs:[
      { q:`Which planet is closest to the Sun?`, ch:[`Venus`,`Earth`,`Mars`,`Mercury`], ans:3, exp:`Mercury is the closest planet to the Sun, orbiting at an average distance of about 58 million km, roughly 0.39 times Earth's distance from the Sun.` },
      { q:`Which planet is known for its prominent ring system, visible even with a small telescope?`, ch:[`Saturn`,`Jupiter`,`Uranus`,`Neptune`], ans:0, exp:`Saturn has the most prominent and famous ring system in the solar system, made mostly of ice particles with some rocky debris. Other giant planets (Jupiter, Uranus, Neptune) have much fainter rings.` },
      { q:`The four inner "terrestrial" planets (Mercury, Venus, Earth, Mars) are primarily composed of:`, ch:[`Hydrogen and helium gas`,`Rock and metal`,`Ice and frozen methane`,`Pure liquid water`], ans:1, exp:`Terrestrial planets have solid, rocky surfaces made of rock and metal, unlike the outer gas giants (Jupiter, Saturn) or ice giants (Uranus, Neptune), which lack solid surfaces.` },
      { q:`Which is the largest planet in our solar system?`, ch:[`Saturn`,`Neptune`,`Jupiter`,`Earth`], ans:2, exp:`Jupiter is by far the largest planet, with a diameter about 11 times that of Earth and a mass more than twice that of all other planets combined.` },
      { q:`An asteroid belt containing millions of rocky objects is located between the orbits of which two planets?`, ch:[`Earth and Mars`,`Jupiter and Saturn`,`Venus and Earth`,`Mars and Jupiter`], ans:3, exp:`The main asteroid belt lies between Mars and Jupiter, containing millions of rocky remnants left over from the formation of the solar system, including the dwarf planet Ceres.` },
      { q:`A single rotation of Earth on its axis (about 24 hours) is responsible for:`, ch:[`Day and night`,`The seasons`,`A full year`,`Ocean tides`], ans:0, exp:`Earth's rotation on its axis, completing roughly once every 24 hours, causes the cycle of day and night as different parts of Earth face toward or away from the Sun.` },
      { q:`Earth's seasons are primarily caused by:`, ch:[`Earth's changing distance from the Sun`,`The tilt of Earth's axis relative to its orbital plane`,`The Moon's gravitational pull`,`Solar flares`], ans:1, exp:`Earth's axis is tilted about 23.5°. As Earth orbits the Sun, this tilt causes different hemispheres to receive more direct sunlight at different times of year, producing seasons. Earth's varying distance from the Sun has only a minor effect.` },
      { q:`Which of these celestial bodies is classified as a dwarf planet, not a full planet?`, ch:[`Mars`,`Mercury`,`Pluto`,`Neptune`], ans:2, exp:`Pluto was reclassified as a dwarf planet by the International Astronomical Union in 2006 because it has not cleared its orbital neighborhood of other debris, one of the criteria for full planet status.` },
      { q:`A comet's glowing tail, which points away from the Sun, is caused mainly by:`, ch:[`The comet's own internal heat`,`Reflection of Earth's light`,`Gravitational pull from nearby planets`,`Solar wind and radiation pressure pushing gas and dust away from the Sun`], ans:3, exp:`As a comet nears the Sun, its ice vaporizes, and solar wind and radiation pressure push the resulting gas and dust away from the Sun, forming a tail that always points roughly away from the Sun regardless of the comet's direction of travel.` },
      { q:`Which planet is often called Earth's "twin" due to similar size and mass, despite having a very different, toxic atmosphere?`, ch:[`Venus`,`Mars`,`Mercury`,`Neptune`], ans:0, exp:`Venus is similar in size and mass to Earth, but its thick carbon dioxide atmosphere creates a runaway greenhouse effect, making its surface the hottest of any planet, around 465°C.` },
      { q:`The Kuiper Belt, home to Pluto and many other icy bodies, is located:`, ch:[`Between Mercury and Venus`,`Beyond the orbit of Neptune`,`Between Mars and Jupiter`,`Inside the asteroid belt`], ans:1, exp:`The Kuiper Belt is a region of icy bodies and dwarf planets extending beyond Neptune's orbit, roughly 30 to 55 astronomical units from the Sun.` },
    ]
  },
  {
    id:`cp114`, cat:`Physical Sciences`, title:`Stars, Galaxies & the Life Cycle of Stars`, diff:`Medium`,
    qs:[
      { q:`Stars generate energy primarily through:`, ch:[`Chemical combustion`,`Radioactive decay`,`Nuclear fusion of hydrogen into helium in their core`,`Gravitational friction alone`], ans:2, exp:`Stars like our Sun shine because nuclear fusion in their cores converts hydrogen nuclei into helium, releasing enormous amounts of energy that radiates outward as light and heat.` },
      { q:`A star's color is primarily an indicator of its:`, ch:[`Age only`,`Distance from Earth`,`Chemical composition alone`,`Surface temperature`], ans:3, exp:`A star's color relates directly to its surface temperature: blue stars are hottest (over 10,000 K), while red stars are coolest (around 3,000 K). Our yellow-white Sun has a surface temperature of about 5,500°C.` },
      { q:`Our galaxy, which contains our solar system, is called the:`, ch:[`Milky Way Galaxy`,`Andromeda Galaxy`,`Triangulum Galaxy`,`Whirlpool Galaxy`], ans:0, exp:`Our solar system is located in the Milky Way Galaxy, a barred spiral galaxy containing an estimated 100-400 billion stars.` },
      { q:`After a star like our Sun exhausts its hydrogen fuel, it will expand into a:`, ch:[`Black hole`,`Red giant`,`Neutron star`,`Supernova remnant only`], ans:1, exp:`Sun-like (low-to-medium mass) stars expand into red giants as they exhaust core hydrogen and begin fusing helium, eventually shedding their outer layers to form a planetary nebula, leaving behind a white dwarf core.` },
      { q:`What is the eventual fate of our Sun, according to current astronomical models?`, ch:[`It will explode as a supernova`,`It will collapse into a black hole`,`It will become a red giant, then shed its outer layers and leave a white dwarf`,`It will simply keep burning forever`], ans:2, exp:`The Sun is not massive enough to explode as a supernova or form a black hole. It will eventually become a red giant, then lose its outer layers as a planetary nebula, leaving a dense white dwarf core.` },
      { q:`Very massive stars (much more massive than the Sun) typically end their lives in a:`, ch:[`Gentle fade into a white dwarf`,`Slow cooling with no explosion`,`Transformation into a new main-sequence star`,`Supernova explosion, potentially leaving a neutron star or black hole`], ans:3, exp:`Massive stars fuse elements up to iron in their cores, then undergo core collapse, triggering a supernova explosion. The remaining core becomes a neutron star or, for the most massive stars, a black hole.` },
      { q:`A black hole is best described as:`, ch:[`A region where gravity is so strong that not even light can escape`,`A region of empty space with nothing inside`,`A dying star that has cooled completely`,`A type of nebula`], ans:0, exp:`A black hole forms when matter is compressed into an extremely small volume, creating gravity so strong that the escape velocity exceeds the speed of light, meaning nothing, including light, can escape once past the event horizon.` },
      { q:`A "nebula" in astronomy refers to:`, ch:[`A collapsed star core`,`A cloud of gas and dust in space, often a site of star formation`,`A type of asteroid`,`A binary star system`], ans:1, exp:`A nebula is a large cloud of interstellar gas (mostly hydrogen) and dust. Dense regions within nebulae can collapse under gravity to form new stars, making nebulae "stellar nurseries."` },
      { q:`Galaxies are generally classified into which main shape categories?`, ch:[`Square, round, and triangular`,`Hot, warm, and cold`,`Spiral, elliptical, and irregular`,`Young, middle-aged, and old only`], ans:2, exp:`Astronomers classify galaxies primarily by shape: spiral galaxies (like the Milky Way, with rotating arms), elliptical galaxies (round or oval, less structured), and irregular galaxies (no defined shape).` },
      { q:`The main sequence of a star's life is the stage during which it:`, ch:[`Has already exploded as a supernova`,`Has fully collapsed into a white dwarf`,`Has not yet ignited nuclear fusion`,`Is steadily fusing hydrogen into helium in its core`], ans:3, exp:`The main sequence is the longest, most stable phase of a star's life, during which it fuses hydrogen into helium in its core at a steady rate. Our Sun has been on the main sequence for about 4.6 billion years.` },
      { q:`Light from the nearest large galaxy to the Milky Way, the Andromeda Galaxy, takes roughly how long to reach Earth?`, ch:[`About 2.5 million years`,`A few seconds`,`About 8 minutes`,`About 13.8 billion years`], ans:0, exp:`Andromeda is about 2.5 million light-years away, meaning the light we observe from it left the galaxy roughly 2.5 million years ago. (8 minutes is the time for sunlight to reach Earth; 13.8 billion years is the estimated age of the universe.)` },
    ]
  },
  {
    id:`cp115`, cat:`Physical Sciences`, title:`Plate Tectonics & Earthquakes Basics`, diff:`Easy`,
    qs:[
      { q:`The theory of plate tectonics describes Earth's outer shell (lithosphere) as being broken into:`, ch:[`A single solid, unmoving plate`,`Several large, slowly moving plates`,`Liquid rock with no solid structure`,`Only two plates, one for land and one for ocean`], ans:1, exp:`Plate tectonics describes Earth's rigid outer lithosphere as broken into several large and small plates that float and slowly move atop the more fluid asthenosphere beneath them.` },
      { q:`At a divergent plate boundary, tectonic plates:`, ch:[`Collide and push together`,`Slide past each other horizontally`,`Move apart from each other`,`Remain completely stationary`], ans:2, exp:`At divergent boundaries, plates move apart, often allowing magma to rise and create new crust, as seen at the Mid-Atlantic Ridge on the ocean floor.` },
      { q:`At a convergent plate boundary, tectonic plates:`, ch:[`Move apart, creating new crust`,`Do not interact at all`,`Only move vertically`,`Collide into each other`], ans:3, exp:`At convergent boundaries, plates move toward and collide with each other, which can cause one plate to be forced beneath another (subduction) or cause both to crumple upward, forming mountains.` },
      { q:`The collision of the Indian and Eurasian tectonic plates over millions of years formed which major mountain range?`, ch:[`The Himalayas`,`The Rocky Mountains`,`The Andes`,`The Alps only`], ans:0, exp:`The ongoing collision between the Indian Plate and the Eurasian Plate, a convergent boundary between two continental plates, has pushed up the Himalayas, home to Earth's tallest peaks.` },
      { q:`At a transform plate boundary, plates primarily:`, ch:[`Move directly apart`,`Slide horizontally past one another`,`Collide head-on`,`Sink beneath each other`], ans:1, exp:`At transform boundaries, plates slide past each other horizontally without creating or destroying crust. California's San Andreas Fault is a well-known example of a transform boundary.` },
      { q:`Most earthquakes occur:`, ch:[`Randomly across the globe with no pattern`,`Only in the middle of tectonic plates`,`Along or near tectonic plate boundaries`,`Only underwater`], ans:2, exp:`The vast majority of earthquakes occur along or near tectonic plate boundaries, where stress builds up as plates interact (colliding, separating, or sliding past each other) and is suddenly released.` },
      { q:`The point on Earth's surface directly above where an earthquake originates underground is called the:`, ch:[`Focus`,`Fault line`,`Seismograph`,`Epicenter`], ans:3, exp:`The epicenter is the point on the surface directly above the earthquake's focus (or hypocenter), which is the actual underground location where the rupture begins.` },
      { q:`An instrument used to detect and measure the vibrations (seismic waves) produced by earthquakes is called a:`, ch:[`Seismograph`,`Barometer`,`Thermometer`,`Anemometer`], ans:0, exp:`A seismograph records ground motion caused by seismic waves, allowing scientists to determine an earthquake's magnitude, location, and depth.` },
      { q:`Subduction occurs when:`, ch:[`Two plates move apart`,`A denser oceanic plate sinks beneath a less dense plate at a convergent boundary`,`Plates slide past each other with no vertical motion`,`Continental crust melts spontaneously`], ans:1, exp:`At many convergent boundaries, the denser oceanic plate is forced (subducted) beneath a less dense continental or oceanic plate, sinking into the mantle. This process is associated with deep ocean trenches and volcanic activity.` },
      { q:`Volcanic activity is commonly associated with which type of plate boundary?`, ch:[`Only transform boundaries`,`Only areas far from plate boundaries`,`Convergent boundaries (especially subduction zones) and divergent boundaries`,`Volcanoes are unrelated to plate tectonics`], ans:2, exp:`Volcanoes commonly form at convergent boundaries, where subducting plates melt and create magma that rises to the surface, and at divergent boundaries, where magma rises to fill the gap as plates separate (like Iceland).` },
      { q:`According to the theory of continental drift (an early precursor to plate tectonics), Earth's continents were once joined together in a single supercontinent called:`, ch:[`Atlantis`,`Gondwana only`,`Laurasia only`,`Pangaea`], ans:3, exp:`Pangaea was the supercontinent that existed roughly 300 to 175 million years ago, before it began breaking apart into the continents we recognize today, a key piece of evidence supporting continental drift and plate tectonics.` },
    ]
  },
  {
    id:`cp116`, cat:`Physical Sciences`, title:`The Rock Cycle & Types of Rocks`, diff:`Medium`,
    qs:[
      { q:`The three main categories of rock are:`, ch:[`Igneous, sedimentary, and metamorphic`,`Hard, soft, and medium`,`Volcanic, oceanic, and continental`,`Crystalline, liquid, and gaseous`], ans:0, exp:`Geologists classify rocks into three main types based on how they form: igneous (from cooled magma/lava), sedimentary (from compacted sediment), and metamorphic (transformed by heat and pressure).` },
      { q:`Igneous rock forms when:`, ch:[`Sediment is compacted and cemented together`,`Molten rock (magma or lava) cools and solidifies`,`Existing rock is subjected to intense heat and pressure without melting`,`Minerals dissolve in water`], ans:1, exp:`Igneous rocks form from the cooling and crystallization of molten rock, either magma underground (forming intrusive igneous rock like granite) or lava at the surface (forming extrusive igneous rock like basalt).` },
      { q:`Sedimentary rock typically forms through which process?`, ch:[`Rapid cooling of lava`,`Extreme heat and pressure transforming existing rock`,`Layers of sediment being compacted and cemented together over time`,`Nuclear reactions in Earth's core`], ans:2, exp:`Sedimentary rocks form as layers of sediment (rock fragments, minerals, or organic material) accumulate and are gradually compacted and cemented together under pressure, often over long time periods.` },
      { q:`Metamorphic rock forms when existing rock is:`, ch:[`Melted completely into magma`,`Dissolved in acid rain`,`Simply exposed to sunlight for a long time`,`Subjected to intense heat and/or pressure, changing its structure without fully melting`], ans:3, exp:`Metamorphic rocks form when existing rock (igneous, sedimentary, or even other metamorphic rock) is transformed by heat, pressure, or chemically active fluids, without fully melting, altering its mineral structure and texture.` },
      { q:`Granite, a common intrusive igneous rock, forms when magma cools:`, ch:[`Slowly, deep underground`,`Quickly at Earth's surface`,`Instantly upon contact with water`,`In outer space`], ans:0, exp:`Granite forms from magma that cools slowly deep underground, allowing large, visible mineral crystals to grow, giving granite its characteristic coarse-grained texture.` },
      { q:`Which rock type commonly contains fossils?`, ch:[`Igneous rock`,`Sedimentary rock`,`Metamorphic rock`,`All rock types equally`], ans:1, exp:`Sedimentary rocks are the primary source of fossils because they form from layers of sediment that can bury and preserve organic remains before compaction and cementation, while igneous and metamorphic formation processes typically destroy fossils.` },
      { q:`Marble is a metamorphic rock that forms from which sedimentary rock, when subjected to heat and pressure?`, ch:[`Sandstone`,`Shale`,`Limestone`,`Conglomerate`], ans:2, exp:`Marble forms from limestone (composed mainly of calcite) that has been subjected to heat and pressure, recrystallizing its mineral structure while remaining primarily calcium carbonate.` },
      { q:`The rock cycle describes how:`, ch:[`Rocks are permanently fixed in one form forever`,`Only igneous rocks can change form`,`Rocks only form once and never change`,`One type of rock can transform into another type over geologic time through various processes`], ans:3, exp:`The rock cycle illustrates that rocks are not permanent — through processes like melting, cooling, weathering, erosion, compaction, and metamorphism, any rock type can eventually transform into any other rock type over geologic time.` },
      { q:`Weathering and erosion primarily contribute to the rock cycle by:`, ch:[`Breaking down rock into sediment that can later form sedimentary rock`,`Melting rock into magma`,`Directly creating metamorphic rock`,`Increasing Earth's overall rock mass`], ans:0, exp:`Weathering breaks rocks down into smaller fragments, and erosion transports this sediment elsewhere. When deposited and compacted over time, this sediment can eventually form new sedimentary rock.` },
      { q:`Obsidian, a volcanic glass with no visible crystals, forms when lava cools:`, ch:[`Extremely slowly underground`,`Extremely rapidly at the surface`,`Under intense metamorphic pressure`,`Through compaction of sediment`], ans:1, exp:`Obsidian forms when lava cools so rapidly at Earth's surface that mineral crystals don't have time to form, resulting in a smooth, glassy texture rather than the crystalline structure seen in slower-cooling igneous rocks like granite.` },
    ]
  },
  {
    id:`cp117`, cat:`Physical Sciences`, title:`Renewable vs Nonrenewable Energy Sources`, diff:`Easy`,
    qs:[
      { q:`A renewable energy source is best defined as one that:`, ch:[`Never runs out under any circumstances`,`Is always more expensive than fossil fuels`,`Can be replenished naturally within a human lifetime`,`Only comes from sunlight`], ans:2, exp:`Renewable energy sources are naturally replenished at a rate comparable to or faster than their use, such as sunlight, wind, and flowing water, unlike fossil fuels which take millions of years to form.` },
      { q:`Which of the following is classified as a nonrenewable energy source?`, ch:[`Wind`,`Solar`,`Hydropower`,`Coal`], ans:3, exp:`Coal is a fossil fuel formed from ancient organic material over millions of years. It is consumed much faster than it can naturally regenerate, making it nonrenewable, unlike wind, solar, and hydropower.` },
      { q:`Fossil fuels like coal, oil, and natural gas originally formed from:`, ch:[`The remains of ancient plants and organisms compressed over millions of years`,`Volcanic ash`,`Ocean saltwater`,`Nuclear reactions in Earth's core`], ans:0, exp:`Fossil fuels formed from the remains of ancient plants and marine organisms that were buried and subjected to heat and pressure over millions of years, converting their stored chemical energy into coal, oil, and natural gas.` },
      { q:`Solar panels generate electricity by:`, ch:[`Burning sunlight as fuel`,`Converting sunlight directly into electrical energy via the photovoltaic effect`,`Using sunlight to spin a turbine directly`,`Storing sunlight as chemical energy in batteries only`], ans:1, exp:`Solar (photovoltaic) panels use semiconductor materials that absorb photons from sunlight and release electrons, directly generating an electric current — this is called the photovoltaic effect.` },
      { q:`Wind turbines generate electricity by:`, ch:[`Burning wind as a chemical fuel`,`Using wind to heat water into steam`,`Converting the kinetic energy of moving air into mechanical energy that turns a generator`,`Absorbing wind directly as electrical energy`], ans:2, exp:`Wind turbines have blades shaped like airfoils that capture the kinetic energy of moving air, which spins a rotor connected to a generator, converting mechanical energy into electrical energy.` },
      { q:`Hydroelectric power plants generate electricity primarily using the energy from:`, ch:[`Burning water`,`Ocean salt concentration`,`Underground heat only`,`Flowing or falling water turning turbines`], ans:3, exp:`Hydroelectric dams use the gravitational potential energy of stored water, which is released and flows through turbines as it falls, converting kinetic energy into electrical energy via generators.` },
      { q:`A major environmental concern with burning fossil fuels for energy is:`, ch:[`They release carbon dioxide and other pollutants, contributing to climate change and air pollution`,`They produce no usable energy`,`They are radioactive`,`They cannot be transported`], ans:0, exp:`Burning fossil fuels releases carbon dioxide (a greenhouse gas contributing to climate change) along with other pollutants like sulfur dioxide and particulates that harm air quality and human health.` },
      { q:`Geothermal energy harnesses:`, ch:[`Energy from ocean tides`,`Heat from Earth's interior`,`Energy stored in plant matter`,`Energy from nuclear fission`], ans:1, exp:`Geothermal energy taps into heat generated within Earth's interior (from radioactive decay and residual heat from planet formation), often using it to produce steam that drives turbines to generate electricity.` },
      { q:`Nuclear power, which generates electricity via nuclear fission of uranium, is generally classified as:`, ch:[`A renewable energy source, since it produces no emissions`,`Neither renewable nor an energy source`,`A nonrenewable energy source, since uranium is a finite, mined resource`,`The same category as solar power`], ans:2, exp:`Although nuclear power produces very low greenhouse gas emissions during operation, it relies on mined uranium, a finite resource, so it is classified as nonrenewable, distinct from renewable sources like solar or wind.` },
      { q:`Biomass energy, derived from organic materials like wood, crop waste, or dedicated energy crops, is generally considered renewable because:`, ch:[`It never produces any emissions when burned`,`It comes from underground reserves`,`It requires no land or resources to produce`,`The organic material can be regrown relatively quickly compared to fossil fuel formation`], ans:3, exp:`Biomass is considered renewable because plant material used as fuel can be regrown over years to decades, much faster than the millions of years required for fossil fuels to form from ancient organic matter.` },
      { q:`Which statement best compares renewable and nonrenewable energy sources in terms of typical daily/seasonal availability?`, ch:[`Nonrenewable sources like coal and natural gas can generate power on demand, while some renewables like solar and wind are intermittent (dependent on weather/time of day)`,`All renewable sources are available 24/7 with no variation`,`Nonrenewable sources are never reliable`,`There is no difference in availability between the two`], ans:0, exp:`Fossil fuel and nuclear plants can generally produce power continuously on demand, while solar power depends on daylight and weather, and wind power depends on wind conditions, making some renewables intermittent without storage solutions.` },
    ]
  },
  {
    id:`cp118`, cat:`Physical Sciences`, title:`Basic Chemistry Safety & Lab Skills`, diff:`Easy`,
    qs:[
      { q:`Before starting any chemistry lab experiment, the most important first step is to:`, ch:[`Taste any unknown chemicals to identify them`,`Read and understand the entire lab procedure and safety instructions`,`Mix chemicals quickly to save time`,`Skip the safety goggles if they seem unnecessary`], ans:1, exp:`Reading and understanding the full procedure and associated safety warnings before beginning ensures you know what to expect, what hazards are involved, and how to handle materials safely throughout the experiment.` },
      { q:`Safety goggles should be worn in the chemistry lab:`, ch:[`Only when handling acids`,`Only during the specific step involving heat`,`At all times during any lab activity involving chemicals or heat`,`Only if requested by a lab partner`], ans:2, exp:`Safety goggles protect eyes from splashes, fumes, and unexpected reactions, and should be worn continuously throughout any lab session involving chemicals, glassware, or heat, not just during specific steps.` },
      { q:`If a chemical spills on your skin during a lab, the first action should generally be to:`, ch:[`Wait to see if irritation develops before doing anything`,`Cover it with a cloth and continue working`,`Apply another chemical to neutralize it without guidance`,`Immediately flush the area with plenty of water`], ans:3, exp:`For most chemical spills on skin, immediately flushing the affected area with large amounts of water (often at an eyewash station or safety shower) for several minutes helps dilute and remove the chemical, reducing injury.` },
      { q:`When diluting a concentrated acid with water, the safe procedure is to:`, ch:[`Add acid slowly to water`,`Add water to the acid`,`Mix them together at the same time from opposite sides`,`It doesn't matter which order you use`], ans:0, exp:`"Always add acid to water," never the reverse. Adding water to concentrated acid can cause a violent, exothermic reaction that spatters dangerous acid. Slowly adding acid to a larger volume of water allows the heat to dissipate more safely.` },
      { q:`Never eat or drink in a chemistry laboratory primarily because:`, ch:[`It is against school rules with no safety reason`,`Food and drink could become contaminated with hazardous chemicals`,`It distracts other students`,`It uses up lab time`], ans:1, exp:`Chemicals, dust, or residues present in the lab environment could contaminate any food or drink, leading to accidental ingestion of hazardous substances, making eating and drinking in labs a serious safety hazard.` },
      { q:`A fume hood in a chemistry lab is primarily used to:`, ch:[`Keep glassware warm`,`Store chemicals long-term`,`Ventilate away hazardous vapors or gases produced during an experiment`,`Measure the mass of chemicals`], ans:2, exp:`A fume hood draws air (and any hazardous fumes, vapors, or gases generated during an experiment) up and out of the lab through a ventilation system, protecting the person working from inhaling dangerous substances.` },
      { q:`Which of these is generally considered proper lab attire?`, ch:[`Open-toed sandals and loose, baggy sleeves`,`Shorts and flip-flops for comfort`,`Any clothing is acceptable as long as goggles are worn`,`Closed-toe shoes, safety goggles, and tied-back long hair`], ans:3, exp:`Proper lab attire includes closed-toe shoes (protecting feet from spills or broken glass), safety goggles, and tied-back hair to prevent it from catching fire or dipping into chemicals — loose sleeves and open-toed shoes increase injury risk.` },
      { q:`If a small chemical fire starts in a beaker during a lab, the appropriate first response is usually to:`, ch:[`Smother it (e.g., with a watch glass or fire blanket) or use an appropriate fire extinguisher`,`Pour water directly on it regardless of the chemical involved`,`Fan it to blow the fire out`,`Ignore it since it will burn out on its own`], ans:0, exp:`Small chemical fires are often best smothered (cutting off oxygen) with a watch glass, lid, or fire blanket, or extinguished with the correct type of extinguisher. Water can react dangerously with certain chemicals (like some metals) and spread others.` },
      { q:`Reading a chemical's Safety Data Sheet (SDS) before use helps you understand:`, ch:[`Only the chemical's cost`,`Hazards, safe handling procedures, and emergency response information for that chemical`,`Only the chemical's color`,`Nothing useful for lab safety`], ans:1, exp:`An SDS provides detailed information about a chemical's hazards (flammability, toxicity, reactivity), safe handling and storage guidelines, and what to do in case of exposure, spill, or fire — essential information before using any chemical.` },
      { q:`When measuring the volume of a liquid in a graduated cylinder, you should read the measurement at:`, ch:[`The highest point of the liquid surface`,`Any angle, since it doesn't affect accuracy`,`Eye level, at the bottom of the meniscus (the curved liquid surface)`,`The very top of the cylinder`], ans:2, exp:`For most liquids (like water), the surface curves slightly due to surface tension, forming a meniscus. Reading the measurement at eye level, at the bottom of this curve, gives the most accurate volume reading.` },
      { q:`Used or waste chemicals from a lab experiment should generally be disposed of by:`, ch:[`Pouring them down the sink drain regardless of type`,`Throwing them in the regular trash can`,`Leaving them on the lab bench for the next class`,`Following specific waste disposal instructions/containers provided for that chemical type`], ans:3, exp:`Different chemicals require different disposal methods (e.g., separate containers for halogenated vs. non-halogenated waste, or acids requiring neutralization) to prevent environmental harm and dangerous reactions — never dispose of unknown or hazardous waste down the drain or in regular trash without specific guidance.` },
    ]
  },
];
